# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: `ds settings` commands: store the secrets in ds.settings (keyring) and show them
#          (the GitHub Copilot token; two Pydantic keys, project and organization; the start.gg
#          token).
# `sync` reads each secret from 1Password first (`op` CLI, item named in _SECRETS); a secret it
# can't find there gets the steps for creating it plus the 1Password item to save it as.
# The Copilot token is different: it is taken from the gh CLI's login (`gh auth token`), with
# no 1Password and no prompt when gh is logged in.
# `--manual` skips 1Password and asks for each one (eg when the 1Password CLI acts up).
# `sync` ends by running `ds ui restart`, as the app reads stored keys only when it starts.
#
# Example CLI Commands:
#   0. Store / replace secrets:              ds settings sync
#   1. Skip 1Password, type each one in:     ds settings sync --manual
#   2. Same, with how to get each one:       ds settings sync --manual --guide
#   3. Show what is stored (masked):         ds settings show
# ---------------------------------------------------------------------------
from __future__ import annotations

import json
import shutil
import subprocess
from typing import Annotated

import typer
from ds.cli.util import run_cmd
from ds.settings import get_settings, set_settings
from pydantic import BaseModel
from rich import print as rprint

__all__ = ["settings_app"]

settings_app = typer.Typer(help="SubCommands for syncing up settings")


class _Secret(BaseModel):
    """What `sync` shows for one secret: where it comes from and how to get it"""

    field: str  # the Settings field / set_settings keyword
    prompt: str
    used_by: str
    url: str
    steps: list[str]
    op_item: str  # 1Password item title (an "API Credential" item; the secret is its `credential` field)
    command: list[str] | None = None  # a local command that prints the secret: tried first, before 1Password


_SECRETS = [
    _Secret(
        field="github_copilot_token",
        prompt="GitHub Copilot token",
        used_by="all ds.ai model calls (the chat, inline AI, evals) while the model is a github-copilot one",
        url="https://cli.github.com",
        steps=[
            "Install the GitHub CLI and run `gh auth login` with the account that has the Copilot seat.",
            "Then run `ds settings sync` again: the token is read from `gh auth token`, nothing to paste.",
            "Run it again after logging in to gh anew: the stored copy doesn't follow gh by itself.",
        ],
        op_item="GitHub Copilot Token",
        command=["gh", "auth", "token"],
    ),
    _Secret(
        field="pydantic_project_api_key",
        prompt="Pydantic project API key",
        used_by="ds.ai model calls while the model is a gateway/ one, and the Spend tab's data",
        url="https://logfire-us.pydantic.dev/delulu-smash/delulu-smash",
        steps=[
            "In the delulu-smash project's settings, create an API key that can proxy model requests",
            "through the Gateway and query the project's traces.",
        ],
        op_item="Pydantic Logfire - DeLulu Smash - Project",
    ),
    _Secret(
        field="pydantic_org_api_key",
        prompt="Pydantic organization API key",
        used_by="ds.data.raw.gateway (the Spend tab's spending limits)",
        url="https://logfire-us.pydantic.dev/delulu-smash/-/settings/api-keys",
        steps=[
            "In the organization's settings, create an API key that can read Gateway settings",
            "(`organization:read_gateway`, `project:read`). The Gateway refuses it for model calls.",
        ],
        op_item="Pydantic Logfire - DeLulu Smash - Org",
    ),
    _Secret(
        field="startgg_api_token",
        prompt="start.gg API token",
        used_by="ds.data.raw.startgg (player sets, tournaments)",
        url="https://start.gg/admin/profile/developer",
        steps=[
            "Log in to start.gg and open the link (Profile > Developer Settings).",
            "Click 'Create new token' and give it a description, eg delulu-smash.",
            "Save and copy it right away: it is shown only once.",
            "Limits: 80 requests per 60 s, 1000 objects per request. The token expires after one year.",
        ],
        op_item="Startgg API Key",
    ),
]


_OP_FIELD = "credential"
_OP_TIMEOUT_S = 60  # `op` waits for the 1Password app to approve (fingerprint / password)
_OP_INTEGRATION_HINT = "In the 1Password app, turn on Settings > Developer > Integrate with 1Password CLI."


def _op_ready() -> str | None:
    """None when `op` can read items, else why not (then every secret gets the guide)"""
    if shutil.which("op") is None:
        return f"1Password CLI (`op`) not found: install `1password-cli`. {_OP_INTEGRATION_HINT}"
    try:
        result = subprocess.run(
            ["op", "account", "list", "--format", "json"],
            capture_output=True,
            text=True,
            timeout=_OP_TIMEOUT_S,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return "1Password CLI did not answer in time."
    if result.returncode != 0 or not json.loads(result.stdout or "[]"):
        return f"1Password CLI has no account. {_OP_INTEGRATION_HINT}"
    return None


def _op_read(secret: _Secret) -> str | None:
    """The secret from 1Password (item `secret.op_item`, any vault), or None if not found"""
    try:
        result = subprocess.run(
            ["op", "item", "get", secret.op_item, "--fields", f"label={_OP_FIELD}", "--reveal"],
            capture_output=True,
            text=True,
            timeout=_OP_TIMEOUT_S,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return None
    return (result.stdout.strip() or None) if result.returncode == 0 else None


def _command_read(command: list[str]) -> str | None:
    """What a local command prints (eg `gh auth token`); None: not installed, failed, empty"""
    if shutil.which(command[0]) is None:
        return None
    try:
        result = subprocess.run(command, capture_output=True, text=True, timeout=_OP_TIMEOUT_S, check=False)
    except subprocess.TimeoutExpired:
        return None
    return (result.stdout.strip() or None) if result.returncode == 0 else None


def _ask(secret: _Secret, stored: object, use_op: bool, guide: bool) -> str | None:
    """One secret from its own command, then 1Password (if use_op), else prompted; None keeps
    the stored one

    The steps show with `guide`, or when 1Password was tried and didn't have it.
    """
    rprint(f"\n[bold]{secret.prompt}[/bold] [dim]- used by {secret.used_by}[/dim]")
    if secret.command:
        shown = " ".join(secret.command)
        value = _command_read(secret.command)
        if value is not None:
            rprint(f"  [green]Read from `{shown}`.[/green]")
            return value
        rprint(f"  [yellow]`{shown}` gave nothing[/yellow] (not installed, or not logged in).")
    if use_op:
        value = _op_read(secret)
        if value is not None:
            rprint(f"  [green]Found in 1Password[/green] (item '{secret.op_item}').")
            return value
        rprint(f"  [yellow]Not found in 1Password[/yellow] (item '{secret.op_item}').")
        guide = True
    rprint(f"  Get it at: {secret.url}")
    if not guide:
        return _prompt(stored)
    steps = [
        *secret.steps,
        " ".join(
            [
                f"Save it in 1Password as an API Credential item named '{secret.op_item}'",
                f"(paste it into the `{_OP_FIELD}` field), so the next `ds settings sync` finds it.",
            ]
        ),
    ]
    for number, step in enumerate(steps, start=1):
        rprint(f"  {number}. {step}")
    return _prompt(stored)


def _prompt(stored: object) -> str | None:
    """Hidden prompt for a secret; Enter keeps the stored value (returns None)"""
    keep = f"Enter keeps {stored}" if stored is not None else "Enter skips"
    return typer.prompt(f"  Paste it ({keep})", hide_input=True, default="", show_default=False) or None


@settings_app.command("sync")
def sync(
    manual: Annotated[
        bool, typer.Option("--manual", help="Skip 1Password and type each secret in (eg if the 1Password CLI acts up)")
    ] = False,
    guide: Annotated[bool, typer.Option("--guide", help="Show the steps for getting each secret asked for")] = False,
) -> None:
    """Store secrets (GitHub Copilot token, Pydantic keys, start.gg token) in the keyring

    The Copilot token comes from the gh CLI's login when there is one. Each other secret is
    read from 1Password (item named per secret) when it is there. One that isn't
    gets the steps for creating it and the 1Password item to save it as, then a prompt; Enter
    keeps what is already stored. `--manual` skips 1Password and asks for every secret.
    Ends by running `ds ui restart`, so the app uses what was stored.
    """
    current = get_settings()
    op_problem = None if manual else _op_ready()
    while op_problem:
        rprint(f"[yellow]{op_problem}[/yellow]")
        if not typer.confirm("Retry 1Password (eg after setting it up)? No types each secret in", default=True):
            break
        op_problem = _op_ready()
    if manual:
        rprint(
            "[dim]Skipping 1Password.[/dim]"
            if guide
            else "[dim]Skipping 1Password. Not sure how to get one? Add `--guide`.[/dim]"
        )
    use_op = not manual and op_problem is None
    answers = {secret.field: _ask(secret, getattr(current, secret.field), use_op, guide) for secret in _SECRETS}
    set_settings(**answers)
    rprint(f"\nCurrent Settings: {get_settings()}")
    # the delulu-smash app reads stored keys once at start: restart it so it uses these
    rprint("\n[dim]Restarting delulu-smash so it picks up the stored keys:[/dim]")
    try:
        run_cmd(["uv", "run", "ds", "ui", "restart"])
    except subprocess.CalledProcessError:
        rprint("[yellow]The restart failed (see above); the secrets are stored. Retry with `ds ui restart`.[/yellow]")


@settings_app.command("show")
def show() -> None:
    """Display current settings"""
    print(get_settings())
